// ===== p193 : de vrais sons de tambour à la place des sons synthétisés =====
// Coups découpés dans des enregistrements libres de Wikimedia Commons : « Ceramic Djembe » (RutgerMuller, CC0) ; tambour sur cadre polonais
// (Swietliste, CC0) ; « Untitled African rhythm » (Kevin MacLeod, CC BY 3.0) ; « Tamate drum-beating at funeral in Bengaluru » (CC BY 3.0).
// Le roulèr est le grave du djembé baissé d'une quinte ; la ravanne est le tambour sur cadre ; le kayamb, le pikèr, le sati et le bobre restent synthétisés
// (aucun enregistrement libre trouvé : à remplacer par des enregistrements de Paris).
const SON193={"rouler0":"","grosse0":"","rouler1":"","grosse1":"","djembe0":"","djembe1":"","djslap0":"","djslap1":"","ravanne0":"","ravanne1":"","ravslap0":"","ravslap1":"","tumba0":"","tumba1":"","conga0":"","conga1":"","tapou0":"","tapou1":"","tapou_boucle":""};
const SON193C=new WeakMap();
function sons193(ctx){if(!ctx)return null;let e=SON193C.get(ctx);if(e)return e.b;e={b:{}};SON193C.set(ctx,e);
 for(const k in SON193){try{const s=atob(SON193[k]),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);const p=ctx.decodeAudioData(u.buffer,b=>{e.b[k]=b},()=>{});if(p&&p.catch)p.catch(()=>{})}catch(x){}}return e.b}
// joue un coup : nom sans numéro (une des variantes au hasard), à l'instant t (temps du contexte), volume v, vitesse (hauteur) r
function coup193(ctx,dest,nom,t,v,r){const B=sons193(ctx);if(!B)return false;const vs=[B[nom+'0'],B[nom+'1']].filter(Boolean);if(!vs.length&&B[nom])vs.push(B[nom]);if(!vs.length)return false;
 const s=ctx.createBufferSource();s.buffer=vs[Math.floor(Math.random()*vs.length)];s.playbackRate.value=(r||1)*(.97+Math.random()*.06);const g=ctx.createGain();g.gain.value=v;s.connect(g);g.connect(dest);s.start(Math.max(ctx.currentTime,t));return true}
// la Table des sons du jeu (p72) : les tambours deviennent de vrais tambours
try{if(typeof I72!=='undefined'){const o={...I72};const at=t=>SND.ctx.currentTime+(t||0),ok=()=>typeof sndPret==='function'&&sndPret();
 const remp=(k,nom,vol,r)=>{I72[k]=(t,v,...a)=>{if(ok()&&coup193(SND.ctx,SND.out,nom,at(t),(v==null?vol[0]:v)*vol[1],r))return;o[k](t,v,...a)}};
 remp('rouler','rouler',[.5,1.5]);remp('grosse','grosse',[.5,1.4]);remp('ravanne','ravanne',[.45,1.5]);remp('ravSlap','ravslap',[.3,1.8]);
 I72.ngoma=(t,v=.4,f=150)=>{if(ok()&&coup193(SND.ctx,SND.out,f<130?'tumba':'conga',at(t),v*1.6))return;o.ngoma(t,v,f)};
 I72.djembe=(t,v=.5)=>{if(!(ok()&&coup193(SND.ctx,SND.out,'djembe',at(t),v*1.5)))o.ngoma(t,v,180)};
 I72.djSlap=(t,v=.4)=>{if(!(ok()&&coup193(SND.ctx,SND.out,'djslap',at(t),v*1.5)))o.ravSlap(t,v)};
 I72.tapou=(t,v=.5)=>{if(!(ok()&&coup193(SND.ctx,SND.out,'tapou',at(t),v*1.5)))o.ngoma(t,v,140)};
 const c0=sndCtx;sndCtx=function(){const c=c0.apply(this,arguments);try{sons193(c)}catch(e){}return c}}}catch(e){}

// ----- le conte (Histoire) reprend seul après 15 s sans toucher à rien, sauf si on l'a mis en pause soi-même avec son bouton -----
setInterval(()=>{try{if(!S||S.fin||!modeHist()||S.autoD||S.autoMan||!S.autoSusp)return;if(performance.now()-calme<15000)return;if(typeof peutConter==='function'&&!peutConter())return;
 S.autoD=1;S.autoSusp=0;grace=performance.now()+3000;proch=0;autoBtn();toast(conteNom()+' : la lecture reprend.')}catch(e){}},1000);

