// ===== de vrais sons pour les cloches, la conque, l'orage, le cœur, l'horloge, le triangle, et les ambiances (mer, vent, pluie) =====
// Enregistrements CC0 de Freesound.org (aperçus, raccourcis et recompressés) ; voir CRED144.
Object.assign(SON193,{"cloche":"","cloche_grave":"","carillon":"","lambi":"","tonnerre":"","gronde":"","coeur":"","tick":"","mer":"","vent":"","pluie":"","maravanne":"","triangle":""});
try{[["BELL.wav (CC0, Freesound n° 378799)", "kgeshev"], ["TollBell.wav (CC0, Freesound n° 73678)", "daytripper"], ["Clock Bell Chimes.wav (CC0, Freesound n° 108249)", "Nick-Nac"], ["Conch.wav (CC0, Freesound n° 78974)", "RoofDog"], ["Thunder Clap (CC0, Freesound n° 672776)", "DaniloSFX"], ["thunder.rumble.ogg (CC0, Freesound n° 486557)", "xUMR"], ["Heartbeat 97 BPM (CC0, Freesound n° 688735)", "Cloud-10"], ["ticking of the clock 01.wav (CC0, Freesound n° 412751)", "blukotek"], ["Ocean Waves on Beach (CC0, Freesound n° 623052)", "goochiano"], ["wind3.wav (CC0, Freesound n° 29532)", "eliasheuninck"], ["Rain heavy 2 (rural) (CC0, Freesound n° 200272)", "jmbphilmes"], ["Egg Shaker - Closed Groove 2 (CC0, Freesound n° 199826)", "connermusician"], ["Triangle_Open_04 (CC0, Freesound n° 349504)", "cabled_mess"]].forEach(c=>CRED144.push(c))}catch(e){}
try{if(typeof PRE72!=='undefined'){const R=(k,nom,v,r)=>{const o=PRE72[k];if(!o)return;const f0=o.f;o.f=()=>{const c=typeof sndPret==='function'&&sndPret();if(!(c&&coup193(c,SND.out,nom,c.currentTime,v,r)))f0()}};
 R('cloche','cloche',.7);R('clocheGrave','cloche_grave',.8);R('carillon','carillon',.55);R('lambi','lambi',.7);R('tonnerre','tonnerre',.9);R('gronde','gronde',.8);R('coeur','coeur',.8);R('tick','tick',.4);
 if(PRE72.coeur)PRE72.coeur.d=5;if(PRE72.tick)PRE72.tick.d=4;
 const t0=I72.triangle;I72.triangle=(t,v=.06)=>{const c=typeof sndPret==='function'&&sndPret();if(!(c&&coup193(c,SND.out,'triangle',c.currentTime+(t||0),v*5)))t0(t,v)}}}catch(e){}
// les ambiances : la mer, le vent et la pluie enregistrés remplacent le bruit filtré, dès que les sons sont décodés (même réglage de volume)
setInterval(()=>{try{if(!SND||!SND.amb||!SND.ctx)return;const B=sons193(SND.ctx);for(const k of ['mer','vent','pluie']){const L=SND.amb[k];if(!L||L.vrai||!B[k])continue;
  const s=SND.ctx.createBufferSource();s.buffer=B[k];s.loop=true;L.F.type='allpass';s.connect(L.F);s.start(0,Math.random()*B[k].duration);try{L.s.stop()}catch(e){}L.s=s;L.vrai=1;L.g.gain.value*=1;
  const g0=L.g;if(!L.fix){L.fix=1;const k2={mer:1.6,vent:2.2,pluie:1.4}[k];const gg=SND.ctx.createGain();gg.gain.value=k2;L.F.disconnect();L.F.connect(gg);gg.connect(g0)}}}catch(e){}},2000);
